package com.videokit.d1input;
import com.videokit.spike.c14.*;import java.io.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import static com.videokit.d1input.InputSinkCheck.*;
/** Tests the existing coordinator itself, including zero outstanding count with a real observer
 * still in its actual original worker tail. Count zero is never a return proof. */
public final class CoordinatorOrderCheck {
 static int cases;
 static void one(boolean ready,String result)throws Exception{
  CompletableFuture<String> original=new CompletableFuture<>();CountDownLatch entered=new CountDownLatch(1);int[] rpc=new int[3];AtomicReference<Throwable> outcome=new AtomicReference<>();
  SinkCoordinator c=new SinkCoordinator("exact_original_task",new SinkCoordinator.Host(){public CompletionStage<String> markReady(String id){rpc[0]++;entered.countDown();return original;}public CompletionStage<Void> abort(String id){rpc[1]++;return CompletableFuture.completedFuture(null);}public CompletionStage<SinkCoordinator.Status> query(String id){rpc[2]++;return CompletableFuture.completedFuture(new SinkCoordinator.Status(ready?SinkCoordinator.HostState.READY:SinkCoordinator.HostState.ABORTED,ready?"controlled_ready_token":null));}},1000);
  c.start();c.validating();Thread caller=new Thread(()->{try{c.finalizeReady(true);}catch(Throwable e){outcome.set(e);}},"original-coordinator-caller");caller.start();
  try{need(entered.await(2,TimeUnit.SECONDS),"original READY method entered");c.abortBeforeReady();need(c.state()==(ready?SinkCoordinator.State.READY:SinkCoordinator.State.ABORTED),"accurate original QUERY terminal first");rejected(c::awaitOriginalCallbacks,"OUTPUT_ORIGINAL_PENDING");
   if(result.equals("CANCEL"))original.completeExceptionally(new CancellationException("private-original-cancel"));else if(result.equals("FAIL"))original.completeExceptionally(new IOException("private-original-failure"));else original.complete(result.equals("DIFFERENT")?"different_late_token":"controlled_ready_token");caller.join(2500);need(!caller.isAlive(),"same original caller returned");
   boolean accepted=ready&&result.equals("SAME");if(accepted)need(outcome.get()==null,"consistent original ACK allowed");else need(outcome.get() instanceof IOException,"late conflict/failure is stable checked error");
   need(c.state()==(ready?SinkCoordinator.State.READY:SinkCoordinator.State.ABORTED)&&(!ready||"controlled_ready_token".equals(c.token())),"late result cannot overwrite immutable terminal/token");c.awaitOriginalCallbacks();need(c.originalCallbacksReturned()&&Arrays.equals(rpc,new int[]{1,1,1}),"same real original callbacks/executor/thread joined; RPC once");cases++;System.out.println("PASS coordinator_order terminal="+c.state()+" late="+result+" sameOriginalCallerAndCallbacksJoined=true");
  }finally{original.complete(ready?"controlled_ready_token":"contradictory_late_token");caller.join(2500);need(!caller.isAlive(),"failure cleanup same caller");c.awaitOriginalCallbacks();need(c.originalCallbacksReturned(),"failure cleanup actual worker joined");}
 }
 static void observerTail()throws Exception{
  ResponseOrderCheck.Response original=new ResponseOrderCheck.Response();original.gateObserver=true;original.complete("controlled_ready_token");SinkCoordinator c=new SinkCoordinator("exact_original_task",new SinkCoordinator.Host(){public CompletionStage<String> markReady(String id){return original;}public CompletionStage<Void> abort(String id){return CompletableFuture.completedFuture(null);}public CompletionStage<SinkCoordinator.Status> query(String id){return CompletableFuture.completedFuture(new SinkCoordinator.Status(SinkCoordinator.HostState.READY,"controlled_ready_token"));}},80);c.start();c.validating();AtomicReference<Throwable> error=new AtomicReference<>();Thread caller=new Thread(()->{try{c.finalizeReady(true);}catch(Throwable t){error.set(t);}},"same-original-coordinator-caller");caller.start();
  try{need(original.entered.await(2,TimeUnit.SECONDS),"same real coordinator observer action entered before tail");caller.join(2500);need(!caller.isAlive()&&error.get()==null&&c.pendingCallbacks()==0&&!c.originalResponsesCompleted(),"counter0 but actual original observer not returned");rejected(c::awaitOriginalCallbacks,"OUTPUT_ORIGINAL_PENDING");Thread actual=original.callbackThread;need(actual.isAlive()&&!c.originalCallbacksReturned(),"actual original worker still retained");System.out.println("OBSERVE coordinatorCounter0OriginalObserverTail thread="+actual.getId()+" alive="+actual.isAlive()+" callbacks="+c.pendingCallbacks()+" responsesComplete="+c.originalResponsesCompleted());original.leave.countDown();c.awaitOriginalCallbacks(1000);need(!actual.isAlive()&&c.originalCallbacksReturned(),"join THAT same actual worker, not a replacement task");cases++;System.out.println("PASS coordinator_order zeroCounter_actualOriginalObserverAndThreadJoined");}finally{original.leave.countDown();caller.join(2500);c.awaitOriginalCallbacks(1000);need(!caller.isAlive()&&c.originalCallbacksReturned(),"tail failure cleanup same originals");}
 }
 public static void main(String[] args)throws Exception{System.out.println("ORIGIN="+SinkCoordinator.class.getProtectionDomain().getCodeSource().getLocation());one(false,"SAME");one(false,"CANCEL");for(String r:List.of("SAME","DIFFERENT","FAIL","CANCEL"))one(true,r);observerTail();System.out.println("DONE coordinatorOrderCases="+cases+" allFiniteGatesReleased=true sameOriginalThreadsJoined=true");}
}
